#include <QByteArray>
#include <QJsonObject>
#include <QString>
#include <atomic>
#include <memory>
#include <stdexcept>
#define private public
#include "native_backend.h"
#undef private
#include "../src/native_backend.cpp"
#include <QTextStream>

int main(int argc,char **argv){
 QCoreApplication app(argc,argv);QJsonArray checks;int passed=0;
 auto test=[&](const QString &name,const std::function<void()> &fn){fn();checks.append(name);++passed;};
 auto reject=[&](const std::function<void()> &fn){bool caught=false;try{fn();}catch(const native::Failure&){caught=true;}native::require(caught,"expected_rejection_missing");};
 try{
  const QString root=argc>1?QString::fromLocal8Bit(argv[1]):QDir::currentPath();std::atomic_bool cancel(false);native::Broker::Impl impl(root,&cancel);
  test(QStringLiteral("actual_pinned_node_capability"),[&]{const auto c=impl.capability();native::require(c.value(QStringLiteral("undetectable")).toBool()&&c.value(QStringLiteral("native_syntax_disabled")).toBool(),"capability_failed");});
  auto cookie=[](const QString &name,const QString &path,const QString &domain,bool hostOnly){return QJsonObject{{QStringLiteral("key"),name},{QStringLiteral("value"),QStringLiteral("fixture-public-test-value")},{QStringLiteral("domain"),domain},{QStringLiteral("path"),path},{QStringLiteral("hostOnly"),hostOnly},{QStringLiteral("secure"),true},{QStringLiteral("httpOnly"),true},{QStringLiteral("expires"),QJsonValue(QJsonValue::Null)},{QStringLiteral("sameSite"),QStringLiteral("lax")}};};
  test(QStringLiteral("cookie_seed_merge_exact_tuple_delete_preserves_other_path"),[&]{native::CookieJar jar;const auto rootCookie=cookie(QStringLiteral("fixture"),QStringLiteral("/"),native::HOST,true);const auto apiCookie=cookie(QStringLiteral("fixture"),QStringLiteral("/api"),native::HOST,true);jar.put(rootCookie);jar.put(apiCookie);jar.merge({},QJsonArray{rootCookie});native::require(jar.values.size()==1&&jar.values[0].value(QStringLiteral("path")).toString()==QStringLiteral("/api"),"cookie_tuple_delete_failed");});
  test(QStringLiteral("cookie_domain_hostonly_httpOnly_path_semantics"),[&]{native::CookieJar jar;jar.absorb({{QByteArray("Set-Cookie"),QByteArray("fixture=one; Path=/api; Secure; HttpOnly; SameSite=Lax")}},QUrl(native::ORIGIN+QStringLiteral("/home")));native::require(jar.snapshot().size()==1,"cookie_parse_failed");const auto c=jar.values[0];native::require(c.value(QStringLiteral("hostOnly")).toBool()&&c.value(QStringLiteral("httpOnly")).toBool()&&c.value(QStringLiteral("sameSite")).toString()==QStringLiteral("lax"),"cookie_attributes_failed");native::require(jar.header(QUrl(native::ORIGIN+QStringLiteral("/api/x"))).contains("fixture="),"cookie_path_send_failed");native::require(!jar.header(QUrl(native::ORIGIN+QStringLiteral("/outside"))).contains("fixture="),"cookie_path_leak");reject([&]{jar.put(cookie(QStringLiteral("bad"),QStringLiteral("/"),QStringLiteral("outside.invalid"),true));});});
  test(QStringLiteral("cookie_expiry_max_age_and_domain_attributes"),[&]{native::CookieJar jar;jar.absorb({{QByteArray("Set-Cookie"),QByteArray("fixture=one; Domain=.114yygh.com; Path=/api; Max-Age=600; Secure")}},QUrl(native::ORIGIN+QStringLiteral("/home")));native::require(jar.snapshot().size()==1&&!jar.values[0].value(QStringLiteral("hostOnly")).toBool()&&jar.values[0].value(QStringLiteral("expires")).isDouble(),"cookie_domain_expiry_failed");jar.absorb({{QByteArray("Set-Cookie"),QByteArray("fixture=gone; Domain=.114yygh.com; Path=/api; Max-Age=0")}},QUrl(native::ORIGIN+QStringLiteral("/home")));native::require(jar.snapshot().isEmpty(),"cookie_expiry_deletion_failed");});
  test(QStringLiteral("normal_security_script_exact_following_stage"),[&]{const QString html=QStringLiteral("<base href='/security/'><script>$_ts.nsd=1;$_ts.cd='fixture';</script><script src='real.js'></script><script src='/business.js'></script>");native::require(impl.normalSource(html,impl.entry)==native::ORIGIN+QStringLiteral("/security/real.js"),"normal_script_mapping_failed");reject([&]{impl.normalSource(QStringLiteral("<script>$_ts.nsd=1;$_ts.cd='x';</script><script src='https://outside.invalid/a.js'></script>"),impl.entry);});});
  test(QStringLiteral("normal_document_cookie_literal_not_challenge"),[&]{native::require(!native::challenge(QByteArray("<html><script>document.cookie='fixture=1';</script><script src='/app.js'></script></html>")),"generic_document_false_positive");native::require(native::challenge(QByteArray("<script>$_ts={};$_ts.nsd=1;$_ts.cd='fixture';</script><script src='/security.js'></script>")),"challenge_not_detected");});
  test(QStringLiteral("same_host_path_allowlist_old_hospital_and_credentials_rejected"),[&]{impl.code=QStringLiteral("H02");reject([&]{impl.wire(QStringLiteral("GET"),native::ORIGIN+QStringLiteral("/jtjk/mobile-service/department/list/H01"));});reject([&]{impl.wire(QStringLiteral("GET"),QStringLiteral("https://user@www.114yygh.com/newhlwyl/mobile/appointmentRegisterHome"));});reject([&]{impl.wire(QStringLiteral("GET"),native::ORIGIN+QStringLiteral("/jtjk/mobile-service/patient/list"));});native::require(impl.dispatchCount==0,"rejected_request_dispatched");});
  test(QStringLiteral("opaque_post_requires_exact_active_method_path"),[&]{reject([&]{impl.wire(QStringLiteral("POST"),native::ORIGIN+QStringLiteral("/jtjk/mobile-service/product/calendar"),{},QByteArray("opaque-not-json"));});native::require(impl.dispatchCount==0,"opaque_unauthorized_dispatched");});
  test(QStringLiteral("bounded_transport_budget_no_network"),[&]{impl.dispatchCount=12;reject([&]{impl.wire(QStringLiteral("GET"),impl.entry);});native::require(impl.dispatchCount==12,"budget_changed");impl.dispatchCount=0;});
  test(QStringLiteral("protocol_ready_requires_generation_two_and_errors_fail_fast"),[&]{impl.accepted=true;impl.ipc="{\"event\":\"ready\",\"generation\":1,\"errors\":[]}\n{\"event\":\"ready\",\"generation\":2,\"errors\":[]}\n";const auto event=impl.wait(QStringLiteral("ready"));native::require(event.value(QStringLiteral("generation")).toInt()==2,"old_ready_returned");for(const auto &kind:{QByteArray("invalid_ipc"),QByteArray("runtime_eof")}){impl.ipc=QByteArray("{\"event\":\"")+kind+QByteArray("\"}\n");reject([&]{impl.wait(QStringLiteral("ready"));});}impl.ipc=QByteArray(native::MAX_IPC+1,'x');reject([&]{impl.drain();});impl.ipc.clear();impl.accepted=false;});
  test(QStringLiteral("opaque_printable_department_ids_and_strict_hospital_codes"),[&]{native::require(native::safeDepartmentCode(QString::fromUtf8("科门-A.2")),"opaque_unicode_department_rejected");native::require(!native::safeDepartmentCode(QStringLiteral("line\nbreak"))&&!native::safeDepartmentCode(QString(161,QLatin1Char('x'))),"unsafe_department_id_accepted");native::require(!native::safeCode(QString::fromUtf8("科门-A.2"))&&native::safeCode(QStringLiteral("H01")),"hospital_code_rule_broadened");});
  test(QStringLiteral("public_post_binds_selected_hospital_before_bootstrap"),[&]{native::Broker broker(root,&cancel);broker.selectHospital(QStringLiteral("H02"));reject([&]{broker.request(QStringLiteral("POST"),QStringLiteral("/jtjk/mobile-service/product/calendar"),{{QStringLiteral("hosCode"),QStringLiteral("H01")},{QStringLiteral("firstDeptCode"),QStringLiteral("root")},{QStringLiteral("secondDeptCode"),QStringLiteral("leaf")}});});native::require(broker.dispatches()==0,"bad_body_dispatched");});
  test(QStringLiteral("cancellation_and_close_without_network"),[&]{cancel.store(true);reject([&]{impl.check();});cancel.store(false);impl.shutdown();native::require(impl.closed&&impl.proc.state()==QProcess::NotRunning,"cleanup_failed");});
  QTextStream(stdout)<<QJsonDocument(QJsonObject{{QStringLiteral("fixture_only"),true},{QStringLiteral("website_requests"),0},{QStringLiteral("passed"),passed},{QStringLiteral("checks"),checks},{QStringLiteral("runtime_hash"),QString::fromLatin1(native::FAST_HASH)}}).toJson(QJsonDocument::Compact)<<Qt::endl;return 0;
 }catch(const std::exception &e){QTextStream(stderr)<<QString::fromUtf8(e.what())<<Qt::endl;return 1;}
}
